 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find diamond motifs: a 2-cell above/below and a pair of 2-cells
    # one row below/above at the adjacent columns.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r][c - 1] == 2 and
                grid[r][c + 1] == 2 and grid[r + 1][c] == 2):
                centers.append((r, c))
    # Join aligned diamond tips with color 1, without overwriting the 2 tips.
    for i, (r1, c1) in enumerate(centers):
        for r2, c2 in centers[i + 1:]:
            if r1 == r2:
                lo, hi = sorted((c1, c2))
                if hi - lo > 2:
                    for c in range(lo + 2, hi - 1):
                        out[r1][c] = 1
            elif c1 == c2:
                lo, hi = sorted((r1, r2))
                if hi - lo > 2:
                    for r in range(lo + 2, hi - 1):
                        out[r][c1] = 1
    return out
